#pragma once
#include "../../support.hpp"
namespace algs {
template<class T>class Deque{std::vector<std::optional<T>>buffer;int head=0,length=0;void ensureCapacity(){if(length<int(buffer.size()))return;std::vector<std::optional<T>>next(buffer.size()*2);for(int i=0;i<length;++i)next[i]=buffer[(head+i)%buffer.size()];buffer.swap(next);head=0;}public:explicit Deque(int capacity=8):buffer(std::max(1,capacity)){}int size()const{return length;}bool isEmpty()const{return !length;}Deque&pushBack(T v){ensureCapacity();buffer[(head+length)%buffer.size()]=std::move(v);++length;return *this;}Deque&pushFront(T v){ensureCapacity();head=(head-1+int(buffer.size()))%buffer.size();buffer[head]=std::move(v);++length;return *this;}std::optional<T>popBack(){if(!length)return {};int i=(head+length-1)%buffer.size();auto v=buffer[i];buffer[i].reset();--length;return v;}std::optional<T>popFront(){if(!length)return {};auto v=buffer[head];buffer[head].reset();head=(head+1)%buffer.size();--length;return v;}std::optional<T>peekFront()const{return length?buffer[head]:std::optional<T>{};}std::optional<T>peekBack()const{return length?buffer[(head+length-1)%buffer.size()]:std::optional<T>{};}std::optional<T>at(int i)const{if(i<0)i+=length;if(i<0||i>=length)return {};return buffer[(head+i)%buffer.size()];}std::vector<T>toArray()const{std::vector<T>r;for(int i=0;i<length;++i)r.push_back(*at(i));return r;}};
}
